styles:
/* Aylık Maliyet Raporu Detayı — modern detay sayfası */
.amrd-page {
  --amrd-primary: #4557a3;
  --amrd-primary-mid: #586495;
  --amrd-accent: #5b6fd6;
  --amrd-muted: #94a3b8;
  --amrd-label: #64748b;
  --amrd-text: #1e293b;
  --amrd-border: #e2e8f0;
  --amrd-surface: #ffffff;
  --amrd-soft: #f8fafc;
  --amrd-shadow: 0 4px 24px rgba(69, 87, 163, 0.08);
  --amrd-radius: 16px;
  width: 100%;
  max-width: 100%;
  min-height: 100%;
  margin: 0;
  padding: 1.25rem 1rem 2.5rem;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--amrd-text);
  background: linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%);
  box-sizing: border-box;
}

@media (min-width: 768px) {
  .amrd-page {
    padding: 1.5rem 1.5rem 2.75rem;
  }
}

@media (min-width: 1200px) {
  .amrd-page {
    padding: 1.75rem 2rem 3rem;
  }
}

.amrd-page *,
.amrd-page *::before,
.amrd-page *::after {
  box-sizing: border-box;
}

/* Toolbar */
.amrd-page .amrd__toolbar {
  order: -20;
  flex: 0 0 auto;
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 0 1rem 0 !important;
  padding: 0 !important;
}

.amrd-page .amrd__toolbar > .row,
.amrd-page .amrd__toolbar .row {
  display: flex !important;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  width: 100% !important;
  margin: 0 !important;
}

.amrd-page .amrd__toolbar .col,
.amrd-page .amrd__toolbar [class*='col-'] {
  flex: 0 1 auto;
  width: auto !important;
  max-width: none;
  padding: 0 !important;
}

.amrd-page .amrd__toolbar .col:last-child,
.amrd-page .amrd__toolbar [class*='col-']:last-child {
  margin-left: auto;
}

.amrd-page .amrd__toolbar .p-button {
  border-radius: 10px;
  font-weight: 600;
  min-height: 2.5rem;
}

/* Hero */
.amrd-page .amrd__hero {
  order: -10;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  margin-bottom: 1.25rem;
  padding: 1.35rem 1.5rem;
  border-radius: var(--amrd-radius);
  background: linear-gradient(135deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
  color: #fff;
  box-shadow: 0 12px 40px rgba(69, 87, 163, 0.25);
}

.amrd-page .amrd__hero-main {
  flex: 1 1 240px;
  min-width: 0;
}

.amrd-page .amrd__eyebrow {
  display: block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-bottom: 0.35rem;
}

.amrd-page .amrd__hero h1 {
  margin: 0 0 0.4rem;
  font-size: clamp(1.2rem, 2.5vw, 1.55rem);
  font-weight: 800;
  line-height: 1.25;
}

.amrd-page .amrd__hero-sub {
  margin: 0;
  font-size: 0.92rem;
  opacity: 0.92;
  line-height: 1.5;
}

.amrd-page .amrd__hero-status {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
}

.amrd-page .amrd__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
}

.amrd-page .amrd__badge--done {
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.35);
  color: #fff;
}

.amrd-page .amrd__badge--pending {
  background: rgba(251, 191, 36, 0.2);
  border: 1px solid rgba(251, 191, 36, 0.45);
  color: #fff7ed;
}

/* Meta link kartı */
.amrd-page .amrd__meta-card {
  width: 100%;
  margin-bottom: 1.25rem;
  background: var(--amrd-surface);
  border: 1px solid var(--amrd-border);
  border-radius: var(--amrd-radius);
  box-shadow: var(--amrd-shadow);
  overflow: hidden;
}

.amrd-page .amrd__meta-links {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.65rem;
  padding: 0.85rem;
}

@media (min-width: 768px) {
  .amrd-page .amrd__meta-links {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.75rem;
    padding: 1rem;
  }
}

.amrd-page .amrd-meta-link {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.9rem 1rem;
  text-decoration: none;
  text-align: left;
  background: #f8fafc;
  border: 1px solid #e8edf5;
  border-radius: 12px;
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}

.amrd-page .amrd-meta-link:hover {
  background: #fff;
  border-color: #c7d2fe;
  box-shadow: 0 4px 16px rgba(69, 87, 163, 0.1);
}

.amrd-page .amrd-meta-link__icon {
  flex: 0 0 auto;
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 0.95rem;
}

.amrd-page .amrd-meta-link__icon--opening {
  background: #eef2ff;
  color: #4557a3;
}

.amrd-page .amrd-meta-link__icon--closing {
  background: #ffedd5;
  color: #ea580c;
}

.amrd-page .amrd-meta-link__icon--broken {
  background: #fef3c7;
  color: #d97706;
}

.amrd-page .amrd-meta-link__body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 0.2rem;
  text-align: left;
}

.amrd-page .amrd-meta-link__label {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748b;
  line-height: 1.3;
}

.amrd-page .amrd-meta-link__action {
  font-size: 0.86rem;
  font-weight: 700;
  line-height: 1.35;
  color: #1e293b;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
}

.amrd-page .amrd-meta-link__action i {
  font-size: 0.72rem;
  color: #4557a3;
  transition: transform 0.15s ease;
}

.amrd-page .amrd-meta-link:hover .amrd-meta-link__action {
  color: #4557a3;
}

.amrd-page .amrd-meta-link:hover .amrd-meta-link__action i {
  transform: translateX(2px);
}

/* Metrik tablosu */
.amrd-page .amrd__metrics-card {
  width: 100%;
  margin-bottom: 1.25rem;
  background: var(--amrd-surface);
  border: 1px solid var(--amrd-border);
  border-radius: var(--amrd-radius);
  box-shadow: var(--amrd-shadow);
  overflow: hidden;
}

.amrd-page .amrd__metrics-card > .form-container,
.amrd-page .amrd__metrics-card .form-container {
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

.amrd-page .amrd__metrics-head {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 1.1rem 1.25rem;
  border-bottom: 1px solid var(--amrd-border);
  background: linear-gradient(180deg, #f8fafc 0%, #fff 100%);
}

.amrd-page .amrd__metrics-head-icon {
  flex: 0 0 auto;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #eef2ff 0%, #e0e7ff 100%);
  color: var(--amrd-primary);
  font-size: 1.15rem;
  box-shadow: 0 4px 14px rgba(69, 87, 163, 0.12);
}

.amrd-page .amrd__metrics-head h2 {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--amrd-primary-mid);
}

.amrd-page .amrd__metrics-head p {
  margin: 0.35rem 0 0;
  font-size: 0.82rem;
  color: var(--amrd-label);
}

/* Metrik kart grid */
.amrd-page .amrd__metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  padding: 1.15rem 1.15rem 1.25rem;
}

@media (max-width: 1199px) {
  .amrd-page .amrd__metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 575px) {
  .amrd-page .amrd__metrics-grid {
    grid-template-columns: 1fr;
    padding: 1rem;
  }
}

.amrd-page .amrd-metric {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1rem;
  border-radius: 14px;
  border: 1px solid var(--amrd-border);
  background: #fff;
  box-shadow: 0 2px 12px rgba(15, 23, 42, 0.04);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  overflow: hidden;
}

.amrd-page .amrd-metric::before {
  content: '';
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: 3px;
  background: var(--amrd-metric-accent, #4557a3);
}

.amrd-page .amrd-metric:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08);
}

.amrd-page .amrd-metric__head {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  min-height: 2.4rem;
}

.amrd-page .amrd-metric__icon {
  flex: 0 0 auto;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 0.95rem;
  background: var(--amrd-metric-icon-bg, #eef2ff);
  color: var(--amrd-metric-icon-color, #4557a3);
}

.amrd-page .amrd-metric__title {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 800;
  line-height: 1.3;
  color: var(--amrd-metric-title, #1e293b);
}

.amrd-page .amrd-metric__stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem;
}

.amrd-page .amrd-metric__stat {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.55rem 0.6rem;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(15, 23, 42, 0.06);
}

.amrd-page .amrd-metric__stat-label {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #64748b;
}

.amrd-page .amrd-metric__stat-label i {
  font-size: 0.68rem;
  opacity: 0.85;
}

.amrd-page .amrd-metric__stat-value {
  font-size: 0.92rem;
  font-weight: 800;
  line-height: 1.2;
  color: var(--amrd-metric-value, #4557a3);
  word-break: break-word;
}

.amrd-page .amrd-metric__stat-value small {
  margin-left: 0.15rem;
  font-size: 0.72rem;
  font-weight: 700;
  opacity: 0.75;
}

/* Kart temaları */
.amrd-page .amrd-metric--opening {
  --amrd-metric-accent: #64748b;
  --amrd-metric-icon-bg: #f1f5f9;
  --amrd-metric-icon-color: #475569;
}

.amrd-page .amrd-metric--purchase {
  --amrd-metric-accent: #6366f1;
  --amrd-metric-icon-bg: #eef2ff;
  --amrd-metric-icon-color: #4f46e5;
}

.amrd-page .amrd-metric--transfer-in {
  --amrd-metric-accent: #0ea5e9;
  --amrd-metric-icon-bg: #e0f2fe;
  --amrd-metric-icon-color: #0284c7;
}

.amrd-page .amrd-metric--transfer-out {
  --amrd-metric-accent: #06b6d4;
  --amrd-metric-icon-bg: #cffafe;
  --amrd-metric-icon-color: #0891b2;
}

.amrd-page .amrd-metric--broken {
  --amrd-metric-accent: #f59e0b;
  --amrd-metric-icon-bg: #fef3c7;
  --amrd-metric-icon-color: #d97706;
}

.amrd-page .amrd-metric--required {
  --amrd-metric-accent: #22c55e;
  --amrd-metric-icon-bg: #dcfce7;
  --amrd-metric-icon-color: #16a34a;
  background: linear-gradient(180deg, #f0fdf4 0%, #ffffff 100%);
}

.amrd-page .amrd-metric--closing {
  --amrd-metric-accent: #f97316;
  --amrd-metric-icon-bg: #ffedd5;
  --amrd-metric-icon-color: #ea580c;
  background: linear-gradient(180deg, #fff7ed 0%, #ffffff 100%);
}

.amrd-page .amrd-metric--diff {
  --amrd-metric-accent: #ef4444;
  --amrd-metric-icon-bg: rgba(255, 255, 255, 0.14);
  --amrd-metric-icon-color: #ffffff;
  --amrd-metric-title: #ffffff;
  --amrd-metric-value: #ffffff;
  background: linear-gradient(135deg, #334155 0%, #1e293b 100%);
  border-color: #334155;
  grid-column: 1 / -1;
}

@media (min-width: 1200px) {
  .amrd-page .amrd-metric--diff {
    grid-column: span 2;
  }
}

.amrd-page .amrd-metric--diff .amrd-metric__stat {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.12);
}

.amrd-page .amrd-metric--diff .amrd-metric__stat-label {
  color: rgba(255, 255, 255, 0.72);
}

.amrd-page .amrd-metric--diff .amrd-metric__stats {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (min-width: 768px) {
  .amrd-page .amrd-metric--diff .amrd-metric__head {
    margin-bottom: 0.15rem;
  }

  .amrd-page .amrd-metric--diff {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 1rem 1.15rem;
  }

  .amrd-page .amrd-metric--diff .amrd-metric__stats {
    flex: 0 0 auto;
    min-width: 280px;
  }
}

/* Onay aksiyonları */
.amrd-page .amrd__actions {
  width: 100% !important;
  margin: 0 !important;
  padding: 1rem 1.25rem 1.25rem !important;
  border-top: 1px solid var(--amrd-border);
  background: var(--amrd-soft);
}

.amrd-page .amrd__actions > .row,
.amrd-page .amrd__actions .row {
  display: flex !important;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.75rem;
  margin: 0 !important;
}

.amrd-page .amrd__actions .p-button-success,
.amrd-page .amrd__actions .p-button.p-button-success {
  border-radius: 10px;
  font-weight: 700;
  min-height: 2.5rem;
  box-shadow: 0 4px 14px rgba(34, 197, 94, 0.25);
}

.amrd-page .amrd__actions label {
  margin: 0 !important;
  padding: 0.5rem 0.85rem;
  border-radius: 999px;
  background: #ecfdf5;
  color: #047857;
  font-weight: 700;
  font-size: 0.82rem;
}

@media (max-width: 767px) {
  .amrd-page .amrd__hero {
    padding: 1.1rem 1.15rem;
  }
}
